window.YCT_EXTRA_EXAMPLES["h7/u6/cast a shadow on"] = ["The bad news cast a shadow on our holiday.", "这个坏消息给我们的假期蒙上了阴影。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/scream"] = ["She screamed when she saw the smoke.", "看到烟雾时她尖声大叫。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/suspend"] = ["They suspended the flight because of strong winds.", "由于强风，他们暂停了飞行。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/crew"] = ["The whole crew worked calmly during the emergency.", "紧急情况下全体机组人员都冷静地工作。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/simulated"] = ["The pilots trained in a simulated cockpit.", "飞行员们在模拟驾驶舱里训练。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/simulator"] = ["The flight simulator feels almost like a real plane.", "这个飞行模拟器感觉几乎像真飞机。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/lifelike"] = ["The model is so lifelike that it looks real.", "这个模型非常生动，看起来像真的。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/submit"] = ["Please submit your report before Friday.", "请在星期五之前提交你的报告。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/awesome"] = ["The view of the stars was truly awesome.", "星空的景象真是了不起。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/telescope"] = ["We watched the moon through a small telescope.", "我们用一架小望远镜观看月亮。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/the naked eye"] = ["Only a few stars are visible to the naked eye.", "只有少数星星能用肉眼看见。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/angle"] = ["He angled the mirror to catch the sunlight.", "他把镜子斜置，以便接住阳光。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/galaxy"] = ["Our galaxy holds billions of stars.", "我们的星系中有数十亿颗恒星。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/cosmic"] = ["Cosmic dust floats between the distant stars.", "宇宙尘埃飘浮在遥远的星辰之间。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/conceivably"] = ["The planet could conceivably support simple life.", "可以想象这颗行星可能支持简单的生命。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/subatomic"] = ["Physicists study subatomic particles in huge machines.", "物理学家在巨大的装置中研究亚原子粒子。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/particle"] = ["A tiny particle of dust got into my eye.", "一小粒灰尘进了我的眼睛。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/invisible"] = ["The gas is invisible but has a strong smell.", "这种气体看不见，但有一股强烈的气味。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/straightforward"] = ["The instructions are quite straightforward to follow.", "这些说明很简单，照着做就行。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/self-discipline"] = ["Learning a language needs patience and self-discipline.", "学一门语言需要耐心和自律。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/fetch"] = ["Could you fetch me a glass of water?", "你能去给我拿杯水来吗？"];
window.YCT_EXTRA_EXAMPLES["h7/u6/muscle"] = ["Regular exercise keeps your muscles strong.", "经常锻炼能让肌肉保持强壮。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/pepper"] = ["He added salt and pepper to the soup.", "他往汤里加了盐和胡椒粉。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/sneeze"] = ["Dust makes me sneeze again and again.", "灰尘让我不停地打喷嚏。"];
window.YCT_EXTRA_EXAMPLES["h7/u6/disc"] = ["He put a music disc into the player.", "他把一张音乐光碟放进播放机里。"];
